// eos-cad-corridor.js — shared helpers for the cable-corridor layout views.
//
// The plan / elevation / cross-section views render the SHARED document's corridor
// objects (ext.corridor.objects[] — cable-run / trench / structure / joint /
// tree-zone) as SVG, over one shared chainage cursor (the CadStore). The 3D pane
// renders doc.features, which are GENERATED by the backend (cable_network's
// generate_object) — regenerateAll/Object below do that round-trip. The 2D views
// render from the object PROPS directly (no backend) so cursor scrubbing re-slices
// instantly. JS twins of emptyos/sdk/cable_render arrangement/profile maths.
// See .claude/rules/cad-layouts.md.

// ── JS twins of the cross-section arrangement + depth maths ──────────────────

export function arrangementOffsets(kind, opts) {
  // → [[label, u, w], ...]; u = lateral, w = vertical within the formation.
  const o = opts || {};
  const n = Math.max(1, parseInt(o.n != null ? o.n : 3, 10));
  const s = +(o.spacing != null ? o.spacing : 0.3);
  const k = (kind || 'flat').toLowerCase();
  if (k === 'flat_n') {
    const start = -(n - 1) / 2 * s;
    return Array.from({ length: n }, (_, i) => ['c' + (i + 1), +(start + i * s).toFixed(6), 0]);
  }
  if (k === 'grid') {
    const rows = Math.max(1, parseInt(o.rows != null ? o.rows : 2, 10));
    const sv = +(o.spacing_v || o.spacingV || s);
    const u0 = -(n - 1) / 2 * s, w0 = -(rows - 1) / 2 * sv;
    const out = []; let c = 1;
    for (let r = 0; r < rows; r++) for (let col = 0; col < n; col++)
      out.push(['c' + (c++), +(u0 + col * s).toFixed(6), +(w0 + r * sv).toFixed(6)]);
    return out;
  }
  if (k === 'trefoil' || k === 'triplex') return [['A', -s / 2, 0], ['B', s / 2, 0], ['C', 0, 0.866 * s]];
  if (k === 'bundle') { const h = s / 2; return [['A', -h, -h], ['B', h, -h], ['C', h, h], ['N', -h, h]]; }
  return [['A', -s, 0], ['B', 0, 0], ['C', s, 0]];   // flat / flat_spaced (3-phase)
}

export function interpDepth(chainage, profile) {
  if (typeof profile === 'number') return profile;
  if (!Array.isArray(profile) || !profile.length) return 0;
  const pts = profile.map(p => [+p[0], +p[1]]).sort((a, b) => a[0] - b[0]);
  if (chainage <= pts[0][0]) return pts[0][1];
  if (chainage >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  for (let i = 1; i < pts.length; i++) {
    const [c0, d0] = pts[i - 1], [c1, d1] = pts[i];
    if (chainage >= c0 && chainage <= c1) { const t = c1 > c0 ? (chainage - c0) / (c1 - c0) : 0; return d0 + t * (d1 - d0); }
  }
  return pts[pts.length - 1][1];
}

export function routeLength(route) {
  let L = 0;
  for (let i = 1; i < (route || []).length; i++) L += Math.hypot(route[i][0] - route[i - 1][0], route[i][1] - route[i - 1][1]);
  return L;
}

export function xyAtChainage(route, ch) {
  if (!route || !route.length) return [0, 0];
  if (route.length === 1) return [route[0][0], route[0][1]];
  let acc = 0;
  for (let i = 1; i < route.length; i++) {
    const seg = Math.hypot(route[i][0] - route[i - 1][0], route[i][1] - route[i - 1][1]);
    if (ch <= acc + seg || i === route.length - 1) {
      const t = seg > 1e-9 ? Math.min(1, Math.max(0, (ch - acc) / seg)) : 0;
      return [route[i - 1][0] + t * (route[i][0] - route[i - 1][0]),
              route[i - 1][1] + t * (route[i][1] - route[i - 1][1])];
    }
    acc += seg;
  }
  const last = route[route.length - 1]; return [last[0], last[1]];
}

// Sections of a run with cumulative chainage spans. Returns {sections:[{sec,start,end,len}], total}.
export function runSpans(run) {
  const sections = []; let acc = 0;
  for (const sec of (run.props.sections || [])) {
    const len = routeLength(sec.route || []);
    sections.push({ sec, start: acc, end: acc + len, len });
    acc += len;
  }
  return { sections, total: acc };
}

export function sectionAtChainage(run, ch) {
  const { sections } = runSpans(run);
  for (const s of sections) if (ch >= s.start && ch <= s.end + 1e-6) return { sec: s.sec, local: ch - s.start };
  return sections.length ? { sec: sections[sections.length - 1].sec, local: ch } : null;
}

export function runFullRoute(run) {
  // Concatenated plan route across sections (joins shared endpoints).
  const out = [];
  for (const sec of (run.props.sections || [])) {
    for (const p of (sec.route || [])) {
      if (!out.length || Math.hypot(p[0] - out[out.length - 1][0], p[1] - out[out.length - 1][1]) > 1e-9) out.push([p[0], p[1]]);
    }
  }
  return out;
}

// The cable-run that drives the elevation + cross-section: the selection if it's a
// cable-run, else the first cable-run in the doc.
export function selectedRun(store) {
  const sel = store.objectByOid(store.selection);
  if (sel && sel.kind === 'cable-run') return sel;
  const runs = store.objectsOfKind('cable-run');
  return runs.length ? runs[0] : null;
}

// ── Tree-protection encroachment (AS 4970) — plan-overlay twin of
//    emptyos/sdk/cable_corridor.tree_encroachment ─────────────────────────────

export function pointSegDist(px, py, ax, ay, bx, by) {
  const dx = bx - ax, dy = by - ay, L2 = dx * dx + dy * dy;
  if (L2 < 1e-12) return Math.hypot(px - ax, py - ay);
  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / L2));
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}

// All cable-run section routes + trench routes as [[x,y],...] (the things a tree
// zone can be encroached by).
export function corridorRoutes(store) {
  const routes = [];
  store.objectsOfKind('cable-run').forEach(r => (r.props.sections || []).forEach(s => {
    if (s.route && s.route.length) routes.push(s.route);
  }));
  store.objectsOfKind('trench').forEach(t => { if (t.props.route && t.props.route.length) routes.push(t.props.route); });
  return routes;
}

export function treeEncroachment(at, nrz, srz, routes) {
  let best = Infinity;
  for (const route of routes) for (let i = 0; i < route.length - 1; i++)
    best = Math.min(best, pointSegDist(at[0], at[1], route[i][0], route[i][1], route[i + 1][0], route[i + 1][1]));
  return { minDist: best, nrz: nrz > 0 && best < nrz, srz: srz > 0 && best < srz };
}

// ── EMF magnetic field (B) — cross-section overlay twin of
//    emptyos/sdk/cable_corridor.b_field_ut ──────────────────────────────────────

const MU0_OVER_2PI = 2.0e-7;

export function bFieldUt(cables, up, zp) {
  // RMS |B| (µT) at (up, zp) from line currents [{u, z, current_a, phase_deg}].
  let bxR = 0, bxI = 0, bzR = 0, bzI = 0;
  for (const c of cables) {
    const du = up - c.u, dz = zp - c.z, d2 = du * du + dz * dz;
    if (d2 < 1e-9) continue;
    const k = MU0_OVER_2PI * c.current_a / d2;
    const ph = c.phase_deg * Math.PI / 180, cr = Math.cos(ph), ci = Math.sin(ph);
    bxR += k * (-dz) * cr; bxI += k * (-dz) * ci;
    bzR += k * du * cr; bzI += k * du * ci;
  }
  return Math.sqrt(bxR * bxR + bxI * bxI + bzR * bzR + bzI * bzI) * 1e6;
}

export function fieldCablesForSection(offsets, depth, currentA) {
  return (offsets || []).map((off, i) => ({
    u: off[1] || 0, z: depth - (off[2] || 0), current_a: currentA || 0, phase_deg: (i % 3) * -120,
  }));
}

export function superposedRiseC(cables, up, zp, rhoKmw) {
  // ΔT (K) at (up, zp) above ambient from N buried line heat sources, by Kennelly's
  // image method in semi-infinite earth (the thermal twin of bFieldUt; mirrors
  // engines/thermal/kennelly.superposed_rise_at). zp/depth are positive-down; the
  // image source sits at -depth so the ground surface (zp=0) stays at ambient.
  // cables: [{u, depth, w}] (w = losses W/m). rhoKmw = soil thermal resistivity K·m/W.
  if (!(rhoKmw > 0)) return 0;
  const k = 1 / rhoKmw;
  let total = 0;
  for (const c of cables) {
    const du = up - c.u;
    const dReal = Math.hypot(du, zp - c.depth);
    const dImage = Math.hypot(du, zp + c.depth);
    if (dReal > 1e-6) total += (c.w / (2 * Math.PI * k)) * Math.log(dImage / dReal);
  }
  return total;
}

export function thermalCablesForSection(offsets, depth, lossesWPerM) {
  return (offsets || []).map((off) => ({
    u: off[1] || 0, depth: depth - (off[2] || 0), w: lossesWPerM || 0,
  }));
}

// ── SVG helpers ──────────────────────────────────────────────────────────────

export const SVGNS = 'http://www.w3.org/2000/svg';

export function svg(tag, attrs, children) {
  const el = document.createElementNS(SVGNS, tag);
  for (const k in (attrs || {})) if (attrs[k] != null) el.setAttribute(k, attrs[k]);
  for (const c of (children || [])) el.appendChild(c);
  return el;
}

// Projector world→pixel for a bbox into (w×h) with padding. flipY for plan (world
// +y up → screen down); no flip for depth sections (depth increases downward).
export function makeProjector(bbox, w, h, pad, opts) {
  const o = opts || {};
  const bw = Math.max(1e-6, bbox.maxx - bbox.minx), bh = Math.max(1e-6, bbox.maxy - bbox.miny);
  const s = Math.min((w - 2 * pad) / bw, (h - 2 * pad) / bh) * (o.scaleMul || 1);
  const ox = pad + ((w - 2 * pad) - bw * s) / 2, oy = pad + ((h - 2 * pad) - bh * s) / 2;
  const project = (x, y) => {
    const px = ox + (x - bbox.minx) * s;
    const py = o.flipY ? (h - (oy + (y - bbox.miny) * s)) : (oy + (y - bbox.miny) * s);
    return [px, py];
  };
  project.scale = s;
  return project;
}

// ── Backend regenerate (objects → doc.features for the 3D pane) ───────────────

// Resolve a kind → its owning app's api_prefix from the object-type registry
// (cached), so regenerate works across apps (cable-network, overhead-line, …).
let _objTypePrefix = null;
export async function objectApiPrefix(kind) {
  if (!_objTypePrefix) {
    _objTypePrefix = {};
    try {
      const r = await fetch('/cad/api/object-types').then((r) => r.json());
      (r.object_types || []).forEach((o) => { _objTypePrefix[o.kind] = o.api_prefix; });
    } catch (e) { /* fall back per-call */ }
  }
  return _objTypePrefix[kind] || '/cable-network/api';
}

export async function regenerateObject(store, oid, opts) {
  const o = opts || {};
  const obj = store.objectByOid(oid);
  if (!obj) return;
  const apiBase = o.apiBase || await objectApiPrefix(obj.kind);
  let res;
  try {
    res = await fetch(apiBase + '/cad/object/' + encodeURIComponent(obj.kind), {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ oid, props: obj.props }),
    }).then(r => r.json());
  } catch (e) { return; }
  if (!res || !res.ok) return;
  const doc = store.doc;
  const old = new Set(obj._raw.feature_ids || []);
  doc.features = (doc.features || []).filter(f => !old.has(f.id));
  doc.features.push(...(res.features || []));
  obj._raw.feature_ids = res.feature_ids || [];
  obj._raw._report = res.report || null;       // stashed for the cross-section readout
  if (o.notify !== false) store.notifyDoc();
}

export async function regenerateAll(store, opts) {
  const o = opts || {};
  for (const obj of store.iterObjects()) {
    await regenerateObject(store, obj.oid, { apiBase: o.apiBase, notify: false });
  }
  store.notifyDoc();
}

// ── Demo corridor (the user's worked example) ────────────────────────────────

export function demoCorridorDoc() {
  const left = [[0, 2], [40, 2]], right = [[0, -2], [40, -2]];
  const conduit = { id_m: 0.207, od_m: 0.225 };
  const objects = [
    { oid: 'trench-l', kind: 'trench', ext: 'corridor',
      props: { route: left, width_m: 1.2, depth_m: 0.9, carries: ['run-l'] } },
    { oid: 'trench-r', kind: 'trench', ext: 'corridor',
      props: { route: right, width_m: 1.2, depth_m: 0.9, carries: ['run-r'] } },
    { oid: 'run-l', kind: 'cable-run', ext: 'corridor',
      props: { mbr_m: 2.0, color: '#d62728', sections: [
        { id: 's1', route: left, profile: 0.9, arrangement: 'flat', n: 3, spacing: 0.3, conduit }] } },
    { oid: 'run-r', kind: 'cable-run', ext: 'corridor',
      props: { mbr_m: 2.0, color: '#3b7dd8', sections: [
        { id: 's1', route: right, profile: 0.9, arrangement: 'flat', n: 3, spacing: 0.3, conduit }] } },
    { oid: 'hdd', kind: 'cable-run', ext: 'corridor',
      props: { mbr_m: 5.0, color: '#c9b400', sections: [
        { id: 'bore', route: [[40, 0], [80, 0]], profile: [[0, 0.9], [5, 3.0], [35, 3.0], [40, 0.9]],
          arrangement: 'flat_n', n: 6, spacing: 3.0 }] } },
    { oid: 'joint', kind: 'joint', ext: 'corridor', props: { at: [40, 0, -0.9], connects: ['run-l', 'run-r', 'hdd'] } },
    { oid: 'wall', kind: 'structure', ext: 'corridor',
      props: { at: [20, 6, -1], size: [4, 2, 3], label: 'Existing wall', existing: true,
               clearance: { horizontal_m: 1.5 } } },
  ];
  return {
    schema: 'eos-cad/1', id: null, name: 'Demo cable corridor', units: 'm',
    params: {}, features: [],
    ext: { corridor: { objects } },
  };
}
